public static void main(String[] args) {
    int result = sum(5, 3);
    System.out.println("Sum: " + result);  // Sum: 8
    printNTimes("Hi", 3);  // Hi Hi Hi
}

public static int sum(int a, int b) {
    return a + b;
}

public static void printNTimes(String msg, int n) {
    for (int i = 0; i < n; i++)
        System.out.print(msg + " ");
}
